rows=[list(map(int,l.split())) for l in open('table3000.tsv')]
diag=[rows[q][q] for q in range(len(rows))]
def mex(s):
    m=0
    while m in s: m+=1
    return m
# recurrence f(q,q)=mex over {f(a,q):a<q} u {f(q,b):b<q}
# f(a,q): a<q, r=q>a so f(a,q)=f(a,a)=diag[a]
# f(q,b): b<q: rows[q][b]
for q in range(1,101):
    S=set(diag[a2] for a2 in range(q)) | set(rows[q][b] for b in range(q))
    m=mex(S)
    if m!=diag[q]:
        print('FAIL', q, 'mex', m, 'diag', diag[q], 'S', sorted(S))
        break
else:
    print('verified to 100')
""}

