rows=[list(map(int,l.split())) for l in open('table3000.tsv')]
diag=[rows[q][q] for q in range(len(rows))]
census={}
for l in open('/home/runner/work/chomp/chomp/GROUND_TRUTH/cache/census_50000.tsv'):
    p=l.split()
    if p[0]=='r' or not p[0].isdigit(): continue
    census[int(p[0])]=(p[1],int(p[2]),int(p[3]),p[6])
# identity: d_n = 2n + 1 - overlap_n
# overlap_n = |{d_0..d_{n-1}} ∩ {f(n,b): b<n}| (all values, but they're all < d_n except dips)
# refine: overlap from live b only
for n in range(1,3001):
    dset=set(diag[:n])  # d_0..d_{n-1}
    rowset=set(rows[n][b] for b in range(n))
    ov=len(dset & rowset)
    if diag[n]!=2*n+1-ov:
        print('identity FAIL at', n, diag[n], 2*n+1-ov)
        break
else:
    print('identity d_n = 2n+1-overlap verified all n<=3000')
# overlap from live b only
for n in range(1,3001):
    dset=set(diag[:n])
    live_rowset=set(rows[n][b] for b in range(n) if census[b][0]=='live')
    stale_rowset=set(rows[n][b] for b in range(n) if census[b][0]=='stale')
    ov_live=len(dset & live_rowset)
    ov_stale=len(dset & stale_rowset)
    ov=len(dset & set(rows[n][b] for b in range(n)))
    if ov_live+ov_stale!=ov:
        print('live/stale split FAIL at', n, ov, ov_live, ov_stale); break
else:
    print('overlap splits as live+stale, all n<=3000')
# check stale overlap is 0
bad=0
for n in range(1,3001):
    dset=set(diag[:n])
    stale_rowset=set(rows[n][b] for b in range(n) if census[b][0]=='stale')
    if dset & stale_rowset:
        bad+=1
        if bad<=5: print('stale overlap nonzero at', n, dset & stale_rowset)
print('rows with stale-overlap:', bad)
""}

